<template><section v-if="clientId" class="history-request"><h3>Need an earlier receipt or balance?</h3><p>Receipts recorded in AuricWell are available above. Payment cards and earlier TherapyNotes history do not transfer automatically. Send billing a private request for earlier records.</p><details><summary>Request past billing records</summary><form @submit.prevent="submit"><label>What do you need?<select v-model="kind"><option value="receipts">Payment receipts</option><option value="balance">Earlier balance or statement</option><option value="superbill">Insurance superbill</option></select></label><div class="dates"><label>From<input v-model="from" type="date" required></label><label>Through<input v-model="through" type="date" :min="from" required></label></div><label>Anything billing should know?<textarea v-model="details" maxlength="2000" rows="3" placeholder="Please do not include card numbers." /></label><button :disabled="busy">{{ busy?'Sending…':'Send request to billing' }}</button></form></details><p v-if="message" role="status">{{ message }}</p><p v-if="error" role="alert">{{ error }}</p></section></template>
<script setup>
import {ref,watch} from 'vue';import api from '../../services/api';const props=defineProps({clientId:[Number,String],agencyId:[Number,String]});const kind=ref('receipts'),from=ref(''),through=ref(''),details=ref(''),busy=ref(false),message=ref(''),error=ref('');let sequence=0;
async function submit(){if(busy.value)return;if(through.value<from.value){error.value='Choose an end date on or after the start date.';return;}const own=sequence;busy.value=true;error.value='';try{const r=await api.post('/guardian-portal/support-tickets',{clientId:Number(props.clientId),topic:'billing',subject:'Request for historical billing records',question:`Please provide my authorized ${kind.value} for ${from.value} through ${through.value}. These records may be held in the previous system.\n\n${details.value.trim()}`});if(own===sequence){message.value=`Your request was sent to billing${r.data?.ticket?.id?` (ticket ${r.data.ticket.id})`:''}. Your team will confirm what is available.`;details.value='';}}catch(e){if(own===sequence)error.value=e.response?.data?.error?.message||'Your request could not be sent.';}finally{busy.value=false;}}
watch(()=>[props.agencyId,props.clientId],()=>{sequence++;message.value='';error.value='';details.value='';from.value='';through.value='';});
</script>
<style scoped>.history-request{padding:22px;border:1px solid var(--border,#dce5ed);border-radius:12px;background:var(--bg-card,#fff)}.history-request p{line-height:1.6}.history-request label{display:grid;gap:8px;margin:14px 0}.history-request input,.history-request select,.history-request textarea{padding:10px;border:1px solid #b9cbdb;border-radius:6px;font:inherit;max-width:100%;box-sizing:border-box}.dates{display:flex;flex-wrap:wrap;gap:16px}.history-request button{padding:12px 18px;border:0;border-radius:8px;background:#2467a7;color:#fff}.history-request [role=alert]{color:#a12222}</style>
